-- The two checklists published on 2026-10-18: Getting Back Behind the Wheel
-- (Driving) and When You Are Still Carrying a Grudge (Forgiveness).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-18`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('getting-back-behind-the-wheel', 'Getting Back Behind the Wheel', 'For getting back to driving after a crash, a near miss, or years out of the driver''s seat. It rebuilds the habit in small steps, starting with the parked car and a quiet loop, and adds one new thing at a time rather than all of it at once.', 'Driving', '["Sit in the parked car with the engine off — the first step is being in the seat, not going anywhere.", "Drive the same quiet loop three times — a route you already know takes the navigating out of it.", "Pick the hour with the least traffic — easy conditions first is how anyone relearns anything.", "Take someone calm in the passenger seat — company now is not a failure to drive alone later.", "Keep the radio off for the first few trips — quiet leaves room for the road instead of your head.", "Know where you could pull over on the route — an exit you can name is what makes setting off possible.", "Add one new thing each time, not three — a bigger road or a longer trip, never both at once.", "Say out loud what went fine afterward — the near misses get remembered without any help from you."]'::jsonb, 'as needed', array['Anxiety', 'Resilience']::text[], 1, '2026-10-18T16:00:00+00:00'::timestamptz),
  ('when-you-are-still-carrying-a-grudge', 'When You Are Still Carrying a Grudge', 'For a resentment you have been carrying for months or years and are tired of. It helps you weigh what it is costing you, tell letting go apart from letting someone back in, and put a boundary where the grudge has been standing in for one.', 'Forgiveness', '["Write down what it has actually cost you — a grudge is easier to weigh once it is specific.", "Count how often it still visits your day — the tally shows you who is carrying what.", "Separate letting go from letting back in — you can stop rehearsing it and still keep your distance.", "Write the letter you are never going to send — the unsent version is where the true sentence lives.", "Give up on getting the apology first — waiting for it hands them the timing as well.", "Decide whether anything still needs saying — some of these need a conversation and most need an ending.", "Notice what the resentment is protecting — often it is standing in for a boundary you never set.", "Put the boundary in place instead — a rule you keep does the job the grudge was doing badly.", "Expect it to come back now and then — letting go happens in several passes, not one."]'::jsonb, 'as needed', array['Anger', 'Self-Compassion']::text[], 1, '2026-10-18T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
